INSERT INTO `produto` VALUES (1,1,'God of War Ragnarök','https://m.media-amazon.com/images/I/819bwWHNMJL.jpg',2022,'Edição Padrão','UM FUTURO NÃO ESCRITO\r\nAtreus busca conhecimento para entender a profecia de \"\"Loki\"\" e definir o papel dele no Ragnarök. Kratos deve se desacorrentar do medo de repetir erros do passado para ser o pai que Atreus precisa.','SKU1',1.00,1.00,1.00,1.00,200.00,280.00,1,2,1,1),(2,3,'Starfield','https://http2.mlstatic.com/D_NQ_NP_776642-MLU73417729993_122023-O.webp',2023,'Edição Padrão','Em Starfield, a história mais importante é a que você conta com seu personagem. Comece a jornada personalizando sua aparência e decidindo seu histórico e atributos. Você será um explorador experiente, um diplomata charmoso, um ciberita furtivo ou algo completamente diferente? A escolha é sua. Decida quem você será e o que se tornará.','SKU2',1.00,1.00,1.00,1.00,200.00,280.00,1,12,11,1),(3,5,'Pokemon Legends Arceus','https://m.media-amazon.com/images/I/71bhNf8QiOS.jpg',2022,'Edição Padrão','Prepare-se para um novo tipo de grande aventura Pokémon em Pokémon Legends: Arceus, um jogo totalmente novo da Game Freak que combina ação e exploração com as raízes de RPG da série Pokémon. Embarque em missões de pesquisa na antiga região de Hisui. Explore extensões naturais para capturar Pokémon selvagens, aprendendo seu comportamento, aproximando-se sorrateiramente e jogando uma Poké Ball bem direcionada. Você também pode jogar a Poké Ball contendo seu Pokémon aliado perto de um Pokémon selvagem para entrar na batalha sem problemas.','SKU3',1.00,1.00,1.00,1.00,300.00,420.00,1,14,2,1),(4,4,'Call of Duty: Black Ops 3','https://m.media-amazon.com/images/I/81bwynfO98L.jpg',2015,'Edição Padrão','Call of Duty: Black Ops III é o jogo mais profundo e ambicioso da série ao combinar três modos de jogo únicos: campanha, multijogador e Zombies. A campanha foi criada para ser partilhada por 4 jogadores online ou desfrutada a solo numa emocionante experiência cinemática. O multijogador será o mais profundo e gratificante da série, com novas formas para subir de nível, modificar a personagem e prepará-la para a batalha. Já o modo Zombies proporciona uma nova experiência com uma narrativa dedicada. Este título introduz um nível de inovação sem precedentes incluindo cenários arrasadores, armamento e habilidades inéditos e a introdução de um novo sistema de movimento fluido e melhorado.','SKU4',1.00,1.00,1.00,1.00,100.00,140.00,1,15,13,1),(5,2,'Resident Evil 2','https://m.media-amazon.com/images/I/71qWdMRpNGL.jpg',2019,'Edição Padrão','Em Resident Evil 2, a ação clássica, exploração tensa e a jogabilidade de resolver quebra-cabeças que definiu a série Resident Evil retorna. Os jogadores se juntam ao policial novato, Leon S. Kennedy, e à estudante universitária, Claire Redfield, que acabam juntos por uma epidemia desastrosa em Raccoon City que transformou sua população em zumbis mortais. Leon e Claire possuem suas próprias campanhas separadas, permitindo que os jogadores vejam a história da perspectiva de ambos os personagens. O destino desses dois personagens favoritos dos fãs está nas mãos dos jogadores conforme eles trabalham juntos para sobreviver e descobrir o que está por trás do terrível ataque à cidade. Será que eles sairão com vida?','SKU5',1.00,1.00,1.00,1.00,100.00,140.00,1,9,15,1),(6,1,'Marvel\'s Spider-Man 2','https://m.media-amazon.com/images/I/81Zh-3T1enL.jpg',2023,'Edição Padrão','Uma cidade sitiada!\r\nOs Spiders Peter Parker e Miles Morales encaram a maior prova de força com e sem suas máscaras enquanto lutam para salvar a cidade, um ao outro e as pessoas que amam do monstruoso Venom e da nova e perigosa ameaça: os simbiontes.','SKU6',1.00,1.00,1.00,1.00,200.00,280.00,1,7,1,1),(7,3,'Forza Horizon 5','https://media.gamestop.com/i/gamestop/11148773.jpg',2021,'Edição Padrão','Sua Maior Aventura Horizon espera por você! Explore as paisagens vibrantes de mundo aberto do México, com diversão e velocidade sem limites em um mundo em constante evolução, incluindo centenas dos melhores carros do mundo.','SKU7',1.00,1.00,1.00,1.00,200.00,280.00,1,13,3,1),(8,5,'The Legend of Zelda: Tears of Kingdom','https://images.kabum.com.br/produtos/fotos/sync_mirakl/464339/xlarge/Jogo-The-Legend-Of-Zelda-Tears-Of-The-Kingdom-Nintendo-Switch-Midia-F-sica_1751918394.jpg',2023,'Edição Padrão','VIVA ESTA AVENTURA INCOMPARÁVEL. Uma aventura épica pela terra e pelos céus de Hyrule aguarda em The Legend of Zelda: Tears of the Kingdom, para o console Nintendo Switch. A aventura será criada por você, em um mundo alimentado pela sua imaginação.','SKU8',1.00,1.00,1.00,1.00,300.00,420.00,1,6,2,1),(9,4,'Assassin\'s Creed Unity','https://cdn.awsli.com.br/600x450/138/138431/produto/7988193/df7d2c8e0b.jpg',2014,'Edição Padrão','UM NOVO HERÓI IMPLACÁVEL PARA UM NOVO MUNDO BRUTAL\r\nJogue como Arno, um tipo de assassino totalmente novo, mais letal que seus antecessores. Cace suas presas com uma gama de novas armas, tais como a Lâmina Fantasma, uma Lâmina Oculta com a capacidade de disparar como uma besta.','SKU9',1.00,1.00,1.00,1.00,100.00,140.00,1,16,7,1),(10,2,'Digimon Story: Cyber Sleuth','https://m.media-amazon.com/images/I/81ws0fAQ2NL.jpg',2017,'Edição Padrão','MUNDOS VÍVIDOS E IMERSIVOS\r\nEmbarque em uma aventura emocionante onde a linha entre o mundo real e o mundo digital é turva.','SKU10',1.00,1.00,1.00,1.00,100.00,125.50,0,17,4,3),(11,1,'Hollow Knight Silksong','https://image.api.playstation.com/vulcan/ap/rnd/202508/2503/d975a2a2d80276d9891d8d3430fb8ec7ed2e4ad807707e76.png',2025,'Edição Padrão','GUARANÁ SHAW ADIDAS','SKU11',1.00,1.00,1.00,1.00,0.00,0.00,1,11,10,2);
/*!40000 ALTER TABLE `produto` ENABLE KEYS */;
UNLOCK TABLES;

